					: `${featureDef(f) || f.feature}를 기준(0)과 비교한다.`,
		},
	];
	if (doc.regime) {
		tiles.push({
			id: "regime",
			group: "entry",
			name: doc.regime === "down" ? "200일 평균 아래만" : `레짐 ${doc.regime}`,
			label: "레짐 게이트",
