+		{
+			id: "direction",
+			group: "entry",
+			name: isLong ? "기준 위면 롱" : "기준 위면 숏",
+			label: changed && fixed == null ? "부호 바뀜" : isLong ? "순방향" : "역추세",
+			tip: directionTip,
+		},
+		{
+			id: "indicator",
+			group: "entry",
+			name: featureName(f),
+			label: f.tradeable === false ? "참고 지표" : "지표",
+			tip:
+				f.tradeable === false
+					? "실시간으로 공개되지 않는 체결을 따라가기만 한 참고 행이다. 매매 지표가 아니다."
