+					? "종가가 200일 평균 아래인 날만 점수를 매기고 매매한다."
+					: `레짐이 ${doc.regime}인 날만 점수를 매기고 매매한다.`,
+		});
+	}
+	tiles.push({
+		id: "fill",
+		group: "fill",
+		name: `편도 ${Number((doc.cost_per_side * 1e4).toFixed(10))}bp`,
+		label: "비용",
+		tip: `편도 ${(doc.cost_per_side * 1e4).toFixed(0)}bp의 거래 비용을 빼고 계산했다.`,
+	});
+	tiles.push({
+		id: "hold",
+		group: "exit",
+		name: `${trial.h}${doc.unit} 보유`,
+		label: "보유 기간",
+		tip: `들어간 뒤 ${trial.h}${doc.unit} 뒤에 청산한다.`,
+	});
+	return tiles;
+}
