export interface ScreenTrial {
	h: number;
	/** Cumulative fraction sums (rule / hold) over the curve's timestamps; converted to percent for display. */
	curve?: { t: number[]; rule: (number | null)[]; hold: (number | null)[] } | null;

export const leadTrial = (f: ScreenFeature) => f.trials.find((t) => t.h === f.lead_h) ?? f.trials[0];

/** The trial for horizon `h` ("lead" = the horizon the verdict is about), falling back to the lead trial. */
export function trialAt(f: ScreenFeature, h: "lead" | number): ScreenTrial {
	if (h === "lead") return leadTrial(f);
	return f.trials.find((t) => t.h === h) ?? leadTrial(f);
}

/** Round axis ticks covering [min, max], always including zero (the curve's baseline). */
export function niceTicks(min: number, max: number): number[] {
	let lo = Math.min(min, max, 0);
	let hi = Math.max(min, max, 0);
	if (!Number.isFinite(lo) || !Number.isFinite(hi)) return [0];
	if (lo === hi) return [0];
	const range = hi - lo;
	const raw = range / 5;
	const mag = 10 ** Math.floor(Math.log10(raw));
	const norm = raw / mag;
	const stepNorm = norm < 1.5 ? 1 : norm < 3.5 ? 2 : norm < 7.5 ? 5 : 10;
	const step = stepNorm * mag;
	const start = Math.ceil(lo / step) * step;
	const end = Math.floor(hi / step) * step;
	const ticks: number[] = [];
	for (let v = start; v <= end + step * 1e-9; v += step) ticks.push(Number(v.toFixed(10)));
	return ticks.length ? ticks : [0];
}

/** UTC date label with dot separators (YYYY.MM.DD), so a day 01 is never read as a January tick. */
export function dateLabel(ts: number): string {
	const d = new Date(ts);
	const pad = (n: number) => String(n).padStart(2, "0");
	return `${d.getUTCFullYear()}.${pad(d.getUTCMonth() + 1)}.${pad(d.getUTCDate())}`;
}

export interface CurveView {
	t: number[];
	rule: number[];
	hold: number[];
	ticks: number[];
	labels: string[];
}

/** Percent curve view for a trial: fraction sums x100, a missing point carries over the previous one. */
export function curveView(trial: ScreenTrial | undefined | null): CurveView | null {
	const curve = trial?.curve;
	if (!curve || !curve.t || curve.t.length < 2) return null;
	const toPercent = (xs: (number | null)[]) => {
		let last = 0;
		return (xs ?? []).map((x) => {
			if (x != null && Number.isFinite(x)) last = x;
			return last * 100;
		});
	};
	const rule = toPercent(curve.rule);
	const hold = toPercent(curve.hold);
	const all = [...rule, ...hold];
	return {
		t: curve.t,
		rule,
		hold,
		ticks: niceTicks(Math.min(...all), Math.max(...all)),
		labels: curve.t.map(dateLabel),
	};
}

export interface ScreenRuleTile {
	id: string;
	group: string;
	name: string;
	label: string;
	tip: string;
}

/** The trading rule as tiles: entry (direction + indicator, plus a down-regime gate), fill cost, and hold/exit. */
export function screenRule(doc: ScreenDoc, f: ScreenFeature, trial: ScreenTrial): ScreenRuleTile[] {
	const fixed = doc.fixed_sign;
